parameters.jsCode:
const raw = $json.output ?? $json.text ?? $json.response ?? $json.message ?? $json;

function parseJsonCandidate(value) {
  if (typeof value === 'object' && value !== null) return value;
  if (typeof value !== 'string') return null;

  const cleaned = value
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

const buyerPersona = parseJsonCandidate(raw);

if (!buyerPersona || !buyerPersona.profileName) {
  return {
    json: {
      ok: false,
      agent: 'edwin-agent-test',
      message: 'No se pudo generar un buyer persona valido',
      rawOutput: raw
    }
  };
}

const today = new Date().toISOString().slice(0, 10);
buyerPersona.profileImage = buyerPersona.profileImage || '';
buyerPersona.metadata = {
  createdAt: today,
  updatedAt: today,
  source: 'AI',
  tags: Array.isArray(buyerPersona.metadata?.tags) ? buyerPersona.metadata.tags : []
};

const demographics = buyerPersona.demographics || {};
const psychographics = buyerPersona.psychographics || {};
const goals = buyerPersona.goals || {};
const imagePrompt = [
  'Photorealistic professional enrollment marketing buyer persona profile portrait.',
  'Show a realistic person, not a celebrity, not a known public figure.',
  `Persona: ${buyerPersona.profileName}.`,
  `Description: ${buyerPersona.description || ''}.`,
  `Age range: ${demographics.ageRange || 'adult'}.`,
  `Location context: ${(demographics.location || []).join(', ') || 'United States'}.`,
  `Education/employment context: ${demographics.educationLevel || ''}, ${demographics.employmentStatus || ''}.`,
  `Traits: ${(psychographics.personalityTraits || []).join(', ')}.`,
  `Goals: ${(goals.primary || []).join(', ')}.`,
  'Neutral clean background, friendly and trustworthy expression, modern realistic portrait, natural lighting, waist-up composition.'
].join(' ');

return {
  json: {
    ok: true,
    agent: 'edwin-agent-test',
    message: 'buyer persona generado, generando imagen de perfil',
    buyerPersona,
    imagePrompt,
    rawOutput: raw
  }
};

const uploadResponse = $json;
const previous = $('Normalize Buyer Persona JSON').item.json;
const buyerPersona = previous.buyerPersona;
const uploadedUrl = uploadResponse.url || uploadResponse.data?.url || uploadResponse.fileUrl || '';

buyerPersona.profileImage = uploadedUrl || buyerPersona.profileImage || '';

return {
  json: {
    ok: true,
    agent: 'edwin-agent-test',
    message: 'todo bien por estos lados',
    buyerPersona,
    profileImageUrl: buyerPersona.profileImage,
    imagePrompt: previous.imagePrompt,
    imageGenerated: Boolean(buyerPersona.profileImage),
    upload: uploadResponse
  }
};
